// Write the number of entries in the Huffman dictionary
std::size_t dict_size = huffman_codes.size();
outfile.write(reinterpret_cast<const char*>(&dict_size), sizeof(dict_size));

for (const auto& pair : huffman_codes) {
    unsigned char character = pair.first;
    const std::string& code = pair.second;

    // Write the character
    outfile.write(reinterpret_cast<const char*>(&character), sizeof(character));

    // Write the length of the Huffman code
    std::size_t code_length = code.size();
    outfile.write(reinterpret_cast<const char*>(&code_length), sizeof(code_length));

    // Write the Huffman code bits
    for (std::size_t i = 0; i < code_length; i += 8) {
        std::bitset<8> byte;
        for (std::size_t j = 0; j < 8 && (i + j) < code_length; ++j) {
            if (code[i + j] == '1') {
                byte.set(7 - j);
            }
        }
        unsigned char byte_value = static_cast<unsigned char>(byte.to_ulong());
        outfile.write(reinterpret_cast<const char*>(&byte_value), sizeof(byte_value));
    }
}
